type orderService struct{ db *sql.DB; stock StockPort }

func (s *orderService) Place(ctx context.Context, req OrderRequest) (int64, error) {
    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil { return 0, err }
    defer tx.Rollback()                       // no-op after Commit (returns ErrTxDone)
    id, err := insertOrder(ctx, tx, req)
    if err != nil { return 0, err }
    if err := s.stock.Reserve(ctx, tx, id); err != nil { return 0, err }
    return id, tx.Commit()
}
